class FakeClock:
    """Time in milliseconds. It moves only when a test sets it or wait() is called (wait advances it by 1 ms)."""
    def __init__(self, now):
        self.now = now
        self.waits = 0
        self.reads = 0

    def __call__(self):
        self.reads += 1
        assert self.reads < 50_000, "clock() was read 50,000 times without wait() being called; call wait() to let time pass instead of spinning"
        return self.now

    def wait(self):
        self.waits += 1
        self.reads = 0
        self.now += 1

    def set(self, now):
        self.now = now
        self.reads = 0


def raises(exception_type, function, *args):
    try:
        function(*args)
    except exception_type:
        return True
    except Exception as error:
        raise AssertionError(f"expected {exception_type.__name__}, got {type(error).__name__}: {error}")
    raise AssertionError(f"expected {exception_type.__name__}, but nothing was raised")
